size_t RegisterJPEGImage(void) {
  const char *version = "JPEG 9";
  const char *description = "Joint Photographic Experts Group JFIF format";
  const char *suffixes[] = { "JPE", "JPEG", "JPG", "JPS", "PJPEG" };
  size_t entry_size = 0;
  size_t i;

  for (i = 0; i < sizeof(suffixes) / sizeof(suffixes[0]); i++) {
    MagickInfo *info = SetMagickInfo(suffixes[i]);
    if (info != (MagickInfo *) NULL) {
      info->decoder = JPEGDecoder;
      info->encoder = JPEGEncoder;
      info->thread_support = MagickLibrarySupportsThreadSafety;
      info->mime_type = "image/jpeg";
      info->description = description;
      info->version = version;

      entry_size += sizeof(*info);

      RegisterMagickInfo(info);
    }
  }

  return entry_size;
}

