#include <string.h>
#include <stddef.h>

size_t RegisterJPEGImage(void) {
    static const char *jpeg_version = "6b";
    const char *description = "JPEG (Joint Photographic Experts Group)";
    const char *mime_type = "image/jpeg";

    size_t count = 0;

    if (SetMagickInfo("JPE", description, mime_type, &count)) {
        MagickBooleanType thread_support = MagickFalse;
        if (strcmp(jpeg_version, "6b") >= 0)
            thread_support = MagickTrue;
        SetDecoderHandler(JPE, ReadJPEGImage, thread_support);
        SetEncoderHandler(JPE, WriteJPEGImage, thread_support);
    }

    if (SetMagickInfo("JPEG", description, mime_type, &count)) {
        MagickBooleanType thread_support = MagickFalse;
        if (strcmp(jpeg_version, "6b") >= 0)
            thread_support = MagickTrue;
        SetDecoderHandler(JPEG, ReadJPEGImage, thread_support);
        SetEncoderHandler(JPEG, WriteJPEGImage, thread_support);
    }

    if (SetMagickInfo("JPG", description, mime_type, &count)) {
        MagickBooleanType thread_support = MagickFalse;
        if (strcmp(jpeg_version, "6b") >= 0)
            thread_support = MagickTrue;
        SetDecoderHandler(JPG, ReadJPEGImage, thread_support);
        SetEncoderHandler(JPG, WriteJPEGImage, thread_support);
    }

    if (SetMagickInfo("JPS", description, mime_type, &count)) {
        MagickBooleanType thread_support = MagickFalse;
        if (strcmp(jpeg_version, "6b") >= 0)
            thread_support = MagickTrue;
        SetDecoderHandler(JPS, ReadJPEGImage, thread_support);
        SetEncoderHandler(JPS, WriteJPEGImage, thread_support);
    }

    if (SetMagickInfo("PJPEG", description, mime_type, &count)) {
        MagickBooleanType thread_support = MagickFalse;
        if (strcmp(jpeg_version, "6b") >= 0)
            thread_support = MagickTrue;
        SetDecoderHandler(PJPEG, ReadJPEGImage, thread_support);
        SetEncoderHandler(PJPEG, WriteJPEGImage, thread_support);
    }

    return count;
}
